";return 14;}for(const Vertex3D& vertex:loaded.mesh.vertices){const Vec4 normal=UnpackNormalSnorm8(vertex.normal);if(!Near(normal.z,-1)){std::cerr<<"OBJ generated normal or handedness conversion failed
