s off
f 1//1 2//1 3//1
f 1 4 2
";loaded=LoadObjMesh(normalObj);if(!loaded||loaded.mesh.indices.size()!=6||loaded.mesh.vertices.size()!=6){std::cerr<<"OBJ explicit and flat normal parsing failed
";return 16;}if(LoadObjMesh("v 0 0 0
f 1 2 3
")){std::cerr<<"Malformed OBJ was accepted
";return 17;}
