";loaded=LoadObjMesh(uvObj);if(!loaded||!Near(loaded.mesh.vertices[0].u,.2f)||!Near(loaded.mesh.vertices[0].v,.3f)||!Near(loaded.mesh.vertices[1].v,.9f)){std::cerr<<"OBJ texture coordinate parsing failed
