    const MeshLoadResult3D imported=LoadAevryndMeshFile(std::filesystem::path(AEVRYND_SOURCE_DIR)/"engine"/"assets"/"model-packs"/"poly-haven"/"rock_09"/"rock_09.aemesh");if(!imported||imported.mesh.vertices.size()!=6628||imported.mesh.indices.size()!=37248||imported.mesh.Bounds().extents.x<.3f){std::cerr<<"Aevrynd mesh import failed
