    const Vec4 packed=UnpackNormalSnorm8(PackNormalSnorm8({0,-1,.5f},0));
    if(!Near(packed.x,0)||!Near(packed.y,-1)||!Near(packed.z,.5f,.005f)||!Near(packed.w,0)){std::cerr<<"Packed normal format failed
";return 10;}
    Mesh3D box=Mesh3D::CreateUnitBox();
    if(!box.Valid()||box.vertices.size()!=24||box.indices.size()!=36){std::cerr<<"Indexed box topology failed
